-- Popula cidades com a lista oficial de municípios do IBGE (5.571, incluindo o
-- Distrito Federal) — achado do usuário em 15/09/2026: a tabela só tinha 39
-- cidades no total (cadastradas uma a uma conforme apareciam num endereço
-- digitado), então o seletor Estado -> Cidade do cadastro de imóvel (e de
-- cliente) mostrava só uma fração das cidades reais — Amazonas, por
-- exemplo, tinha só 3 das 62 cidades existentes.
--
-- Fonte: API pública do IBGE (servicodados.ibge.gov.br/api/v1/localidades/municipios),
-- consultada em 15/09/2026. Nome do estado usado pra casar com a tabela
-- `estados` (nome oficial, sem sigla) — os 27 nomes bateram exatamente, sem
-- nenhum ajuste manual necessário.
--
-- Idempotente: ON CONFLICT em (nome, estado_id) — a constraint
-- @@unique([nome, estado_id]) do schema já cobre isso. Rodar de novo não
-- duplica nada. As 39 cidades que já existiam (cadastradas manualmente antes
-- desta migração) NÃO são tocadas — o INSERT só adiciona o que falta.

insert into cidades (nome, estado_id, regiao)
select v.nome, e.id, v.regiao
from (values
  ('Alta Floresta D''Oeste', 'Rondônia', 'Região Norte'),
